diff --git a/src/ui/lib/look-for.test.ts b/src/ui/lib/look-for.test.ts
new file mode 100644
index 0000000..d97b1d5
--- /dev/null
+++ b/src/ui/lib/look-for.test.ts
@@ -0,0 +1,227 @@
+import assert from "node:assert/strict";
+import { describe, it } from "node:test";
+import type { ReviewDocument, Source } from "../../schema/types.ts";
+import {
+  claimsFromLookFor,
+  lookForBuckets,
+  lookForClaims,
+  lookForKey,
+  lookForOwnerLabel,
+  openTargetForSource,
+  parseLookForBullet,
+  selectionForLookFor,
+} from "./look-for.ts";
+
+const cookie = {
+  id: "cookie",
+  title: "Session cookie helper",
+  lookFor: ["Breaking. `setSessionCookie` throws when the caller passes `httpOnly: false`."],
+  part: "Session cookie",
+};
+
+const login = {
+  id: "login",
+  title: "Login route",
+  lookFor: ["For `rememberMe = false`, compare the cookie: old code permits script access."],
+  part: "Session cookie",
+};
+
+const docs = {
+  id: "docs",
+  title: "README wording",
+  part: "README",
+};
+
+describe("parseLookForBullet", () => {
+  it("reads the four risk tags and leaves the sentence", () => {
+    assert.deepEqual(parseLookForBullet("Breaking. Throws when httpOnly is false."), {
+      tag: "Breaking",
+      body: "Throws when httpOnly is false.",
+    });
+    assert.deepEqual(parseLookForBullet("Subtle. [#12](source:s1) wants HttpOnly cookies."), {
+      tag: "Subtle",
+      body: "[#12](source:s1) wants HttpOnly cookies.",
+    });
+    assert.deepEqual(parseLookForBullet("Race. Two tabs can both write the cookie."), {
+      tag: "Race",
+      body: "Two tabs can both write the cookie.",
+    });
+    assert.deepEqual(parseLookForBullet("Perf. The helper copies the options object."), {
+      tag: "Perf",
+      body: "The helper copies the options object.",
+    });
+  });
+
+  it("leaves unknown prefixes in the body", () => {
+    assert.deepEqual(parseLookForBullet("For rememberMe = false, compare the cookie."), {
+      body: "For rememberMe = false, compare the cookie.",
+    });
+    assert.deepEqual(parseLookForBullet("breaking. lowercase is not a tag."), {
+      body: "breaking. lowercase is not a tag.",
+    });
+    assert.deepEqual(parseLookForBullet("Breaking."), {
+      body: "Breaking.",
+    });
+  });
+});
+
+describe("lookForClaims", () => {
+  it("lists document claims then group claims in stack order", () => {
+    const claims = lookForClaims(
+      {
+        lookFor: [
+          "[#12](source:s1) also asks logout to clear the session cookie. No hunk touches `src/api/logout.ts`.",
+          "Subtle. [#12](source:s1) wants sessions that client scripts cannot read.",
+        ],
+      },
+      [cookie, login, docs],
+    );
+    assert.deepEqual(
+      claims.map((claim) => ({
+        key: claim.key,
+        owner: claim.owner.kind === "document" ? "Overview" : lookForOwnerLabel(claim.owner),
+        tag: claim.tag,
+        sourceIds: claim.sourceIds,
+      })),
+      [
+        {
+          key: "document:0",
+          owner: "Overview",
+          tag: undefined,
+          sourceIds: ["s1"],
+        },
+        {
+          key: "document:1",
+          owner: "Overview",
+          tag: "Subtle",
+          sourceIds: ["s1"],
+        },
+        {
+          key: "group:cookie:0",
+          owner: "01 Session cookie helper",
+          tag: "Breaking",
+          sourceIds: [],
+        },
+        {
+          key: "group:login:0",
+          owner: "02 Login route",
+          tag: undefined,
+          sourceIds: [],
+        },
+      ],
+    );
+  });
+
+  it("omits empty lookFor", () => {
+    assert.deepEqual(lookForClaims({}, [docs]), []);
+    assert.deepEqual(claimsFromLookFor({ kind: "document" }, []), []);
+  });
+
+  it("buckets claims by owner with counts and tags", () => {
+    const claims = lookForClaims(
+      {
+        lookFor: [
+          "[#12](source:s1) also asks logout to clear the session cookie.",
+          "Subtle. [#12](source:s1) wants sessions that client scripts cannot read.",
+        ],
+      },
+      [cookie, login, docs],
+    );
+    assert.deepEqual(
+      lookForBuckets(claims).map((bucket) => ({
+        owner: lookForOwnerLabel(bucket.owner),
+        count: bucket.claims.length,
+        tags: bucket.tags,
+      })),
+      [
+        { owner: "Overview", count: 2, tags: ["Subtle"] },
+        { owner: "01 Session cookie helper", count: 1, tags: ["Breaking"] },
+        { owner: "02 Login route", count: 1, tags: [] },
+      ],
+    );
+  });
+
+  it("builds keys and selections from the owner", () => {
+    const owner = { kind: "group" as const, id: "login", title: "Login route", index: 2 };
+    assert.equal(lookForKey(owner, 0), "group:login:0");
+    assert.deepEqual(selectionForLookFor(owner), { kind: "group", id: "login" });
+    assert.deepEqual(selectionForLookFor({ kind: "document" }), { kind: "overview" });
+  });
+});
+
+describe("openTargetForSource", () => {
+  const ticket: Source = { id: "s1", kind: "ticket", label: "#12" };
+  const pin: Source = {
+    id: "c1",
+    kind: "pr-comment",
+    label: "alice on PR #12",
+    author: "alice",
+    body: "Throws?",
+    path: "src/auth/session.ts",
+    side: "new",
+    line: 4,
+  };
+  const document: ReviewDocument = {
+    version: 1,
+    source: { baseRef: "main", headRef: "HEAD" },
+    size: "small",
+    title: "HttpOnly session cookies",
+    summary: "Cookie helper and login route.",
+    sources: [ticket, pin],
+    lookFor: ["[#12](source:s1) also asks logout to clear the session cookie."],
+    groups: [
+      {
+        id: "cookie",
+        title: "Session cookie helper",
+        why: "The login route needs one helper.",
+        summary: "`setSessionCookie` applies the options.",
+        suggestedOrder: 0,
+        sources: ["c1"],
+        hunkRefs: [{ path: "src/auth/session.ts", oldStart: 1, oldLines: 20, newStart: 1, newLines: 40 }],
+      },
+      {
+        id: "login",
+        title: "Login route",
+        why: "[#12](source:s1) requires HttpOnly cookies.",
+        summary: "The login route uses the helper.",
+        suggestedOrder: 1,
+        sources: ["s1"],
+        hunkRefs: [{ path: "src/api/login.ts", oldStart: 10, oldLines: 8, newStart: 10, newLines: 24 }],
+      },
+    ],
+  };
+  const claims = lookForClaims(document, document.groups);
+
+  it("opens a line pin on the group that covers the path", () => {
+    assert.deepEqual(openTargetForSource(pin, claims, document), {
+      selection: { kind: "group", id: "cookie" },
+      commentId: "c1",
+    });
+  });
+
+  it("opens the first lookFor that cites the source", () => {
+    assert.deepEqual(openTargetForSource(ticket, claims, document), {
+      selection: { kind: "overview" },
+      lookForKey: "document:0",
+    });
+  });
+
+  it("falls back to the group that lists the source", () => {
+    const orphan: Source = { id: "s9", kind: "commit", label: "abc123" };
+    const withCommit = {
+      ...document,
+      sources: [...(document.sources ?? []), orphan],
+      groups: document.groups.map((group) =>
+        group.id === "login" ? { ...group, sources: ["s1", "s9"] } : group,
+      ),
+    };
+    assert.deepEqual(openTargetForSource(orphan, lookForClaims(withCommit, withCommit.groups), withCommit), {
+      selection: { kind: "group", id: "login" },
+    });
+  });
+
+  it("falls back to overview when nothing owns the source", () => {
+    const extra: Source = { id: "s8", kind: "transcript", label: "Cursor session" };
+    assert.deepEqual(openTargetForSource(extra, claims, document), { selection: { kind: "overview" } });
+  });
+});

diff --git a/src/ui/lib/look-for.ts b/src/ui/lib/look-for.ts
new file mode 100644
index 0000000..fb07cf5
--- /dev/null
+++ b/src/ui/lib/look-for.ts
@@ -0,0 +1,152 @@
+import { padIndex } from "../../schema/types.ts";
+import { citationIds, groupIdForPinnedSource, isLinePinned } from "../../schema/source.ts";
+import type { ReviewDocument, Source } from "../../schema/types.ts";
+import type { Selection } from "./selection.ts";
+
+export const LOOK_FOR_TAGS = ["Subtle", "Breaking", "Race", "Perf"] as const;
+
+export type LookForTag = (typeof LOOK_FOR_TAGS)[number];
+
+const LOOK_FOR_TAG_RE = /^(Subtle|Breaking|Race|Perf)\.\s+(.*)$/;
+
+export type LookForOwner =
+  | { kind: "document" }
+  | { kind: "group"; id: string; title: string; index: number; part?: string };
+
+export type LookForClaim = {
+  key: string;
+  owner: LookForOwner;
+  index: number;
+  tag?: LookForTag;
+  text: string;
+  body: string;
+  sourceIds: string[];
+};
+
+export type LookForGroup = {
+  id: string;
+  title: string;
+  lookFor?: readonly string[];
+  part?: string;
+};
+
+export function parseLookForBullet(text: string): { tag?: LookForTag; body: string } {
+  const match = LOOK_FOR_TAG_RE.exec(text);
+  if (match === null) {
+    return { body: text };
+  }
+  const tag = match[1];
+  const body = match[2];
+  if (tag === undefined || body === undefined || body === "") {
+    return { body: text };
+  }
+  return { tag: tag as LookForTag, body };
+}
+
+export function lookForKey(owner: LookForOwner, index: number): string {
+  return owner.kind === "document" ? `document:${index}` : `group:${owner.id}:${index}`;
+}
+
+export function lookForOwnerLabel(owner: LookForOwner): string {
+  if (owner.kind === "document") {
+    return "Overview";
+  }
+  return `${padIndex(owner.index)} ${owner.title}`;
+}
+
+export function selectionForLookFor(owner: LookForOwner): Selection {
+  return owner.kind === "document" ? { kind: "overview" } : { kind: "group", id: owner.id };
+}
+
+export function claimsFromLookFor(owner: LookForOwner, items: readonly string[] | undefined): LookForClaim[] {
+  return (items ?? []).map((text, index) => {
+    const parsed = parseLookForBullet(text);
+    const claim: LookForClaim = {
+      key: lookForKey(owner, index),
+      owner,
+      index,
+      text,
+      body: parsed.body,
+      sourceIds: citationIds(text),
+    };
+    if (parsed.tag !== undefined) {
+      claim.tag = parsed.tag;
+    }
+    return claim;
+  });
+}
+
+export function lookForClaims(document: { lookFor?: readonly string[] }, groups: readonly LookForGroup[]): LookForClaim[] {
+  const claims = claimsFromLookFor({ kind: "document" }, document.lookFor);
+  groups.forEach((group, i) => {
+    const owner: LookForOwner = {
+      kind: "group",
+      id: group.id,
+      title: group.title,
+      index: i + 1,
+    };
+    if (group.part !== undefined) {
+      owner.part = group.part;
+    }
+    claims.push(...claimsFromLookFor(owner, group.lookFor));
+  });
+  return claims;
+}
+
+export type LookForBucket = {
+  owner: LookForOwner;
+  claims: LookForClaim[];
+  tags: LookForTag[];
+};
+
+export function lookForBuckets(claims: readonly LookForClaim[]): LookForBucket[] {
+  const buckets: LookForBucket[] = [];
+  for (const claim of claims) {
+    const last = buckets[buckets.length - 1];
+    const sameOwner =
+      last !== undefined &&
+      ((claim.owner.kind === "document" && last.owner.kind === "document") ||
+        (claim.owner.kind === "group" && last.owner.kind === "group" && last.owner.id === claim.owner.id));
+    if (sameOwner && last !== undefined) {
+      last.claims.push(claim);
+      if (claim.tag !== undefined && !last.tags.includes(claim.tag)) {
+        last.tags.push(claim.tag);
+      }
+      continue;
+    }
+    buckets.push({
+      owner: claim.owner,
+      claims: [claim],
+      tags: claim.tag !== undefined ? [claim.tag] : [],
+    });
+  }
+  return buckets;
+}
+
+export type SourceOpenTarget = {
+  selection: Selection;
+  lookForKey?: string;
+  commentId?: string;
+};
+
+export function openTargetForSource(
+  source: Source,
+  claims: readonly LookForClaim[],
+  document: ReviewDocument,
+): SourceOpenTarget {
+  if (isLinePinned(source)) {
+    const groupId = groupIdForPinnedSource(document, source);
+    if (groupId !== undefined) {
+      return { selection: { kind: "group", id: groupId }, commentId: source.id };
+    }
+  }
+  const claim = claims.find((item) => item.sourceIds.includes(source.id));
+  if (claim !== undefined) {
+    return { selection: selectionForLookFor(claim.owner), lookForKey: claim.key };
+  }
+  const named = document.groups.find((group) => (group.sources ?? []).includes(source.id));
+  if (named !== undefined) {
+    return { selection: { kind: "group", id: named.id } };
+  }
+  return { selection: { kind: "overview" } };
+}
